fn visit_rows(snapshot:&TiffSnapshot,p:&mut RowWriter<'_,'_>)->Result<(),ValueError>{        p.checkpoint()?;let mut rows=1usize;let mut counted=0usize;
        for ifd in &snapshot.ifds{rows=rows.checked_add(1).and_then(|n|n.checked_add(ifd.storage.chunks.len())).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"TIFF row count overflow"))?;for tag in &ifd.entries{rows=rows.checked_add(1).and_then(|n|n.checked_add(value_count(&tag.values))).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"TIFF row count overflow"))?;p.check_rows(rows)?;counted=counted.checked_add(1).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"TIFF traversal count overflow"))?;if counted%256==0{p.checkpoint()?;}}}p.check_rows(rows)?;
        p.insert_key("tiff_document",1,&[Cell::Text(&snapshot.schema),Cell::Text(match snapshot.byte_order{TiffByteOrder::LittleEndian=>"littleEndian",TiffByteOrder::BigEndian=>"bigEndian"})])?;
        for(ordinal,ifd)in snapshot.ifds.iter().enumerate(){let ifd_id=p.insert("tiff_ifd",&[Cell::Integer(1),Cell::Integer(integer(ordinal)?),Cell::Text(storage_name(ifd.storage.kind)),Cell::Integer(i64::from(ifd.storage.offsets_kind.to_u16())),Cell::Integer(i64::from(ifd.storage.byte_counts_kind.to_u16()))])?;for(chunk_ordinal,chunk)in ifd.storage.chunks.iter().enumerate(){p.insert("tiff_chunk",&[Cell::Integer(ifd_id),Cell::Integer(integer(chunk_ordinal)?),Cell::Blob(chunk)])?;}
            for(ordinal,tag)in ifd.entries.iter().enumerate(){let tag_id=p.insert("tiff_tag",&[Cell::Integer(ifd_id),Cell::Integer(integer(ordinal)?),Cell::Integer(i64::from(tag.tag)),Cell::Integer(i64::from(tag.values.kind().to_u16()))])?;
                match &tag.values{
                    TiffValues::Byte(v)=>integers(p,"tiff_byte_value",tag_id,v.iter().copied().map(i64::from))?,TiffValues::Ascii(v)=>integers(p,"tiff_ascii_value",tag_id,v.iter().copied().map(i64::from))?,TiffValues::Short(v)=>integers(p,"tiff_short_value",tag_id,v.iter().copied().map(i64::from))?,TiffValues::Long(v)=>integers(p,"tiff_long_value",tag_id,v.iter().copied().map(i64::from))?,TiffValues::Rational(v)=>rationals(p,"tiff_rational_value",tag_id,v.iter().map(|&(n,d)|(i64::from(n),i64::from(d))))?,TiffValues::SByte(v)=>integers(p,"tiff_signed_byte_value",tag_id,v.iter().copied().map(i64::from))?,TiffValues::Undefined(v)=>integers(p,"tiff_undefined_value",tag_id,v.iter().copied().map(i64::from))?,TiffValues::SShort(v)=>integers(p,"tiff_signed_short_value",tag_id,v.iter().copied().map(i64::from))?,TiffValues::SLong(v)=>integers(p,"tiff_signed_long_value",tag_id,v.iter().copied().map(i64::from))?,TiffValues::SRational(v)=>rationals(p,"tiff_signed_rational_value",tag_id,v.iter().map(|&(n,d)|(i64::from(n),i64::from(d))))?,TiffValues::Float(v)=>for(ordinal,value)in v.iter().enumerate(){p.insert_float("tiff_float_value",&[Cell::Integer(tag_id),Cell::Integer(integer(ordinal)?),Cell::Float32(f32::from_bits(value.bits))],FLOAT)?;},TiffValues::Double(v)=>for(ordinal,value)in v.iter().enumerate(){p.insert_float("tiff_double_value",&[Cell::Integer(tag_id),Cell::Integer(integer(ordinal)?),Cell::Real(f64::from_bits(value.bits))],DOUBLE)?;},
                }
            }
        }Ok(())}
